mapper.select:
SELECT COUNT(1) FROM sys_menu_role mr INNER JOIN sys_menu m ON m.id = mr.menu_id WHERE mr.role_id = #{roleId}
AND m.title LIKE CONCAT('%', #{query.title}, '%')
AND m.name LIKE CONCAT('%', #{query.name}, '%')
AND m.status = #{query.status}

SELECT m.id, m.title, m.name, m.path, m.menu_type, m.status FROM sys_menu_role mr INNER JOIN sys_menu m ON m.id = mr.menu_id WHERE mr.role_id = #{roleId}
AND m.title LIKE CONCAT('%', #{query.title}, '%')
AND m.name LIKE CONCAT('%', #{query.name}, '%')
AND m.status = #{query.status}
ORDER BY m.menu_rank, m.id

SELECT COUNT(1) FROM sys_menu_role mr INNER JOIN sys_role r ON r.id = mr.role_id WHERE mr.menu_id = #{menuId}
AND r.role_code LIKE CONCAT('%', #{query.roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{query.roleName}, '%')
AND r.status = #{query.status}

SELECT r.id, r.role_code, r.role_name, r.status FROM sys_menu_role mr INNER JOIN sys_role r ON r.id = mr.role_id WHERE mr.menu_id = #{menuId}
AND r.role_code LIKE CONCAT('%', #{query.roleCode}, '%')
AND r.role_name LIKE CONCAT('%', #{query.roleName}, '%')
AND r.status = #{query.status}
ORDER BY r.role_code
